/**
 * Authenticates a user session against the remote identity provider.
 * This block documents behavior in prose and must be rejected by lean_gate.
 * @param token opaque session token from the client
 * @returns whether the token is currently valid
 */
export function authenticate(token: string): boolean {
  return Boolean(token);
}
export function refresh(token: string): string {
  return token;
}
